class Doc:
    def __init__(self):
        self._text = ''
        self._done = []
        self._undone = []
        self._depth = 0
        self._stack = []

    def text(self):
        return self._text

    def begin_group(self):
        self._depth += 1
        if self._depth == 1:
            self._stack.append([])

    def end_group(self):
        if self._depth == 0:
            raise RuntimeError('end_group without matching begin_group')
        self._depth -= 1
        if self._depth == 0:
            edits = self._stack.pop()
            if edits:
                self._done.append(('group', edits))

    def _record(self, edit):
        if self._depth > 0:
            self._stack[-1].append(edit)
        else:
            self._done.append(('single', edit))

    def _apply(self, edit):
        kind, pos, s = edit
        if kind == 'insert':
            self._text = self._text[:pos] + s + self._text[pos:]
        else:
            self._text = self._text[:pos] + self._text[pos + len(s):]

    def _invert(self, edit):
        kind, pos, s = edit
        return ('delete' if kind == 'insert' else 'insert', pos, s)

    def insert(self, pos, s):
        if pos < 0 or pos > len(self._text):
            raise IndexError(pos)
        edit = ('insert', pos, s)
        self._apply(edit)
        self._record(edit)

    def delete(self, pos, n):
        if pos < 0 or pos + n > len(self._text):
            raise IndexError(pos)
        edit = ('delete', pos, self._text[pos:pos + n])
        self._apply(edit)
        self._record(edit)

    def undo(self):
        if self._depth > 0:
            raise RuntimeError('undo while a group is open')
        if not self._done:
            return
        step = self._done.pop()
        kind, payload = step
        if kind == 'group':
            for edit in reversed(payload):
                self._apply(self._invert(edit))
        else:
            self._apply(self._invert(payload))
        self._undone.append(step)

    def redo(self):
        if self._depth > 0:
            raise RuntimeError('redo while a group is open')
        if not self._undone:
            return
        step = self._undone.pop()
        kind, payload = step
        if kind == 'group':
            for edit in payload:
                self._apply(edit)
        else:
            self._apply(payload)
        self._done.append(step)

